export interface IndexAttemptSnapshot {
  id: number;
  status: ValidStatuses | null;
  from_beginning: boolean;
  new_docs_indexed: number;
  docs_removed_from_index: number;
  total_docs_indexed: number;
  error_msg: string | null;
  error_count: number;
  /** Unresolved errors, whole entities such as a drive or channel included. */
  open_error_count: number;
  /** Unresolved document-level errors, the ones a targeted reindex can retry. */
  open_doc_error_count: number;
  full_exception_trace: string | null;
  time_started: string | null;
  time_updated: string;
  /** When a finished attempt ended. `time_updated` also moves on checkpoint cleanup. */
  time_finished: string | null;
  /** Indexed under the FUTURE search settings of a running model switch. */
  is_new_model: boolean;
  /** A one-off run over a window outside the pair's incremental cursor, such as an added scope. */
  is_backfill: boolean;
}

// Mirror of `evolvxsi.db.index_attempt_metrics_models.IndexAttemptStage`. The
// declaration order is the canonical pipeline order, which the API serializes
// and the stage details popover renders. Keep in sync with the Python enum.
export const INDEX_ATTEMPT_STAGES = [
  "CONNECTOR_VALIDATION",
  "PERMISSION_VALIDATION",
  "CHECKPOINT_LOAD",
  "CONNECTOR_FETCH",
  "HIERARCHY_UPSERT",
  "DOC_BATCH_STORE",
  "DOC_BATCH_ENQUEUE",
  "QUEUE_WAIT",
  "DOCPROCESSING_SETUP",
  "BATCH_LOAD",
  "DOC_DB_PREPARE",
  "IMAGE_PROCESSING",
  "CHUNKING",
  "CONTEXTUAL_RAG",
  "EMBEDDING",
  "EMBEDDING_RATE_LIMIT_WAIT",
  "EMBEDDING_PROVIDER_THROTTLE_WAIT",
  "DOC_LOCK_ACQUIRE_WAIT",
  "ENRICHMENT_PREP",
  "VECTOR_DB_WRITE",
  "POST_INDEX_DB_UPDATE",
  "COORD_LOCK_ACQUIRE_WAIT",
  "COORDINATION_UPDATE",
  "FINALIZATION",
  "GC_COLLECT",
  "BATCH_UNACCOUNTED",
  "BATCH_TOTAL",
] as const;

export type IndexAttemptStage = (typeof INDEX_ATTEMPT_STAGES)[number];

export type StageScope = "ATTEMPT_LEVEL" | "BATCH_LEVEL";

export interface IndexAttemptStageMetric {
  stage: IndexAttemptStage;
  scope: StageScope;
  event_count: number;
  total_duration_ms: number;
  avg_duration_ms: number | null;
  std_dev_duration_ms: number | null;
  min_duration_ms: number | null;
  max_duration_ms: number | null;
  time_first_event: string | null;
  time_last_event: string | null;
}

export interface IndexAttemptStageMetricsResponse {
  index_attempt_id: number;
  stages: IndexAttemptStageMetric[];
}

